[{"order":1,"type":"heading","text":"Parallel Execution, Sharding, and Reporters in Playwright"},{"order":2,"type":"paragraph","text":"As your test suite grows, running tests sequentially becomes a bottleneck. Playwright provides robust built-in capabilities for parallel execution, test sharding across multiple machines or CI jobs, and advanced reporting options to analyze results effectively."},{"order":3,"type":"subheading","text":"Configuring Parallel Execution"},{"order":4,"type":"paragraph","text":"By default, Playwright runs test files in parallel to maximize performance. You can control this behavior globally in your playwright.config.ts file or via the Command Line Interface."},{"order":5,"type":"code","text":"import { defineConfig } from '@playwright/test';

export default defineConfig({
  // Fully parallelize tests within files and across files
  fullyParallel: true,
  // Limit workers in CI to prevent resource exhaustion
  workers: process.env.CI ? 2 : undefined,
});"},{"order":6,"type":"bullet_point","text":"fullyParallel: Runs all tests in all files in parallel. Tests must be designed to be completely independent."},{"order":7,"type":"bullet_point","text":"workers: Defines the maximum number of concurrent worker processes. Can be a fixed number or a percentage string like "50%"."},{"order":8,"type":"subheading","text":"Test Sharding"},{"order":9,"type":"paragraph","text":"Sharding allows you to split your test suite across multiple CI jobs or machines. Playwright divides the total test files evenly based on the current shard index and total shards."},{"order":10,"type":"code","text":"npx playwright test --shard=1/3
npx playwright test --shard=2/3
npx playwright test --shard=3/3"},{"order":11,"type":"paragraph","text":"When running in CI environments like GitHub Actions, you can matrix your jobs to automatically handle sharding without manual intervention."},{"order":12,"type":"subheading","text":"Configuring and Using Reporters"},{"order":13,"type":"paragraph","text":"Playwright comes with several built-in reporters such as list, dot, line, html, json, and junit. You can also configure multiple reporters simultaneously in your configuration file."},{"order":14,"type":"code","text":"import { defineConfig } from '@playwright/test';

export default defineConfig({
  reporter: [
    ['list'],
    ['json', { outputFile: 'results.json' }],
    ['html', { open: 'never' }],
  ],
});"},{"order":15,"type":"bullet_point","text":"List Reporter: Provides a detailed, line-by-line output of test execution."},{"order":16,"type":"bullet_point","text":"HTML Reporter: Generates a rich, interactive self-contained folder with traces, screenshots, and videos."},{"order":17,"type":"bullet_point","text":"JUnit/JSON Reporters: Ideal for CI/CD integrations to parse test results into dashboards or monitoring tools."}]
